# final audio: voice on top, the player's song (ducked under the voice), quiet bed (side-chained to the voice), sound effects
cd "$(dirname "$0")"
ffmpeg -loglevel error -y -i voice.wav -i song.wav -i bed.wav -i sfx.wav -filter_complex "[0:a]asplit=3[v][sc][sc2];[2:a][sc]sidechaincompress=threshold=0.02:ratio=6:attack=20:release=400[bedd];[1:a][sc2]sidechaincompress=threshold=0.03:ratio=3:attack=10:release=250[song];[song]volume=0.42[s];[bedd]volume=0.35[b];[3:a]volume=0.38,alimiter=limit=0.6[f];[v][s][b][f]amix=inputs=4:normalize=0,loudnorm=I=-14:TP=-1.5:LRA=11,aresample=48000[out]" -map "[out]" -c:a pcm_s16le mix.wav
